/* @autogenerated */
import { Component, viewChildren } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { LocalRouteDirective } from './local-route.directive';

@Component({
  imports: [LocalRouteDirective],
  template: `
    <ng-template localRoute="a" initial></ng-template>
    <ng-template localRoute="b" fallback="true"></ng-template>
    <ng-template localRoute="c" [initial]="false" fallback="false"></ng-template>
  `,
})
class HostComponent {
  readonly routes = viewChildren(LocalRouteDirective);
}

describe('LocalRouteDirective', () => {
  it('detects fallback and initial flags as boolean attributes', () => {
    const fixture = TestBed.createComponent(HostComponent);
    fixture.detectChanges();
    const [a, b, c] = fixture.componentInstance.routes();

    expect(a.isInitial()).toBeTrue();
    expect(a.isFallback()).toBeFalse();
    expect(b.isFallback()).toBeTrue();
    expect(b.isInitial()).toBeFalse();
    expect(c.isInitial()).toBeFalse();
    expect(c.isFallback()).toBeFalse();
  });
});
